export type ResearchStatus = 'InDevelopment' | 'Researched'
export type Confidence = 'High' | 'Medium' | 'Low'
export type RelationshipType = 'Champion' | 'ActiveEngagement' | 'EmergingConnection' | 'KeyLeader'

