export interface Competitor {
  id: string
  name: string
  research_status: ResearchStatus
  website_url?: string
  hq?: string
  scale?: string
  description?: string
  corporate_posture?: string
  corporate_synthesis_confidence?: Confidence
  mapped_service_lines: string[]
  threat_level?: 'High' | 'Medium' | 'Watch'
}

export interface Differentiator { id: string; competitor_id: string; title: string; description: string; order_index: number }
export interface CompetitorSignal {
  id: string; competitor_id: string; headline: string; signal_type: string
  source_name: string; source_url?: string; signal_date: string
  what_happened: string; why_it_matters: string
  added_context?: string; service_line_tags: string[]
}
export interface StrategicMove {
  id: string; competitor_id: string; title: string; confidence: Confidence
  description: string; featured_signal_ids: string[]
}
export interface ServiceLinePositioning {
  id: string; competitor_id: string; service_line: string; positioning_summary: string
  confidence: Confidence; supporting_points: { title: string; description: string }[]
}
export interface QuestionForCompany {
  id: string; competitor_id: string; service_line: string; question_text: string
  indegene_perspective?: string
}
export interface CompetitorRelationship {
  id: string; competitor_id: string; person_name: string; title: string; company?: string
  relationship_type: RelationshipType; description: string; linkedin_url?: string; source_url?: string
}
export interface StrategicRadarPattern {
  id: string; pattern_type: 'RecurringMove' | 'ServiceLinePattern' | 'CompanyBlindSpot'
  title: string; description: string; contributing_competitor_ids: string[]; contributing_signal_ids: string[]
}
// Account-tied strategic hypothesis + next best steps (Strategic Radar)
export interface StrategicHypothesis {
  id: string; competitor_id: string; title: string; hypothesis: string
  confidence: Confidence; account_ids: string[]
  indegene_angle: string; next_best_steps: string[]
}
// Cross-signal triangulation (Signal Feed)
export interface SignalTriangulation {
  id: string; title: string; competitor_ids: string[]; signal_ids: string[]
  synthesis: string; implication: string; confidence: Confidence
}

